rows = load_pass(2)
by_var = {}
for r in rows:
    v = r['variant']
    by_var.setdefault(v, [0, 0])
    by_var[v][0] += (1 if r['correct'] else 0)
    by_var[v][1] += 1
scores = {v: c / max(1, n) for v, (c, n) in by_var.items()}
base_s = scores.get('original', 0.0)
cands = [(s, tag) for tag, s in scores.items() if tag != 'original']
best_s, best_tag = max(cands)
if best_s > base_s:
    if list_named_edits():
        load_named_edit(best_tag)
    print('KEEPING', best_tag, best_s, '>', base_s)
else:
    drop_edit()
    print('WITHDRAWING_AT_TEST', scores)
```

